INSERT INTO `moderation_presets` VALUES
(1,'room','This room is unacceptable to the hotel management.',1),
(3,'user','Do not excessively repeat identical or similar statements. (spamming).',1),
(4,'user','Please report the scam to www.BoonBoards.com with VALID video proof under the Scam Reports section.',1),
(5,'user','Click on the user and press the ignore button to prevent speech from this person in the future.',1),
(6,'user','Please suggest, ask, or request about it on BoonBoards.com under the Help & Support section.',1),
(7,'user','Your language and/or behavior is unacceptable. Please behave appropriately or expect further action to be taken.',1),
(8,'user','Whoa! Your username is contains invalid characters or is generally inappropriate. Please change your username promptly to avoid getting permanently banned from the hotel.',1);
